  if ($ln =~ /\.\s*$/) { push @stmts, $buf; $buf = ''; }
}
push @stmts, $buf if $buf =~ /\S/;

my %po;   # subject -> predicate -> [objects]
for my $st (@stmts) {
  $st =~ s/^\s+|\s+$//g;
  $st =~ s/\.\s*$//;
  next unless length $st;
  my ($subj, $rest) = $st =~ /^(\S+)\s*(.*)$/s;
  next unless defined $rest && length $rest;
  for my $item (split /\s*;\s*/, $rest) {
    $item =~ s/^\s+|\s+$//g;
