    my ($p, $o) = $item =~ /^(\S+)\s+(.*)$/s;
    next unless defined $o;
    for my $obj (split /\s*,\s*/, $o) {
      $obj =~ s/^\s+|\s+$//g;
      next unless length $obj;
      $obj =~ s/^"(.*)"(?:\^\^\S+)?$/$1/;   # strip literal quotes/datatype
      push @{ $po{$subj}{$p} }, $obj;
    }
  }
}
