  printf "%-46s %3d%s\n", $d, $n, ($n > 10 ? '  <-- >10 BUSY' : '');
}
print "\n--- per-course counts (alternative reading of criterion 3) ---\n";
for my $c (sort keys %perCourse) {
  my $n = scalar keys %{ $perCourse{$c} };
  printf "%-16s %3d%s  (dept=%s)\n", $c, $n, ($n > 10 ? '  >10' : ''), (defined $courseDept{$c} ? $courseDept{$c} : '?');
}
print "\nexcluded (graduated on/before $REF): ", join(", ", map {"$_ ($gradSeen{$_})"} sort keys %gradSeen), "\n";
print "busy departments (aggregate reading): $nb\n";

print "\n--- professor evaluation ---\n";
my @rows;
for my $p (sort keys %po) {
  my ($role) = vals($p,'uni:role');
  next unless defined $role;
  next unless $role =~ /professor/i;
  my $lc = lc $role;
  my $full = ($lc =~ /assistant|associate|adjunct|visiting|emerit/) ? 0 : 1;
  my ($name) = vals($p,'uni:hasName');
  my @depts = vals($p,'uni:worksIn');
  my @countries = map { $uniCountry{$deptUni{$_}} } @depts;
  my %seen; my @uc = grep { defined $_ && !$seen{$_}++ } @countries;
  my $euDept   = grep { defined $uniCountry{$deptUni{$_}} && $EU{ $uniCountry{$deptUni{$_}} } } @depts;
  my $busyDept = grep { $busy{$_} } @depts;
  printf "%-22s full=%d eu=%d busy=%d countries=[%s]  role='%s'\n",
    $name, $full, ($euDept?1:0), ($busyDept?1:0), join(", ", @uc), $role;
  push @rows, [$name, join(", ", @uc)] if $full && $euDept && $busyDept;
}
print "\n--- EXPECTED RESULT SET (query semantics) ---\n";
printf "%-22s | %s\n", $_->[0], $_->[1] for @rows;
print "count=", scalar(@rows), "\n";
